WITH with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN island_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS island_id_tier, island_id, MAX(event_time) AS last_seen, SIZE(COLLECT_SET(page)) AS num_pages, SUM(CASE WHEN event_type = 'page_view' THEN island_id ELSE 0 END) AS page_view_island_id, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, ROUND(SUM(new_group_flag) / NULLIF(COUNT(CASE WHEN page = '/home' THEN 1 END), 0), 2) AS new_group_flag_per_home, MAX(event_time) AS last_event_time, PERCENT_RANK() OVER (PARTITION BY CASE WHEN island_id >= 8 THEN 'LARGE' ELSE 'SMALL' END ORDER BY SIZE(COLLECT_SET(page)) DESC) AS num_pages_percent_rank FROM islands GROUP BY CASE WHEN island_id >= 8 THEN 'LARGE' ELSE 'SMALL' END, island_id ORDER BY island_id DESC;
